//! Per Apple CPU, the A64 forms its Apple clang profile does not have,
//! and the chip-varying features each form requires.
use super::{AbsentForm, AbsentGroup};

/// The varying features, by bit of `requires`: the order of `Feature`.
#[cfg(test)]
pub(super) const FEATURES: [&str; 45] = ["FEAT_AFP", "FEAT_AMUv1", "FEAT_AMUv1p1", "FEAT_BF16", "FEAT_CPA", "FEAT_CSSC", "FEAT_ECV", "FEAT_FAMINMAX", "FEAT_FGT", "FEAT_FGT2", "FEAT_FP8", "FEAT_FPAC", "FEAT_FPACCOMBINE", "FEAT_FPMR", "FEAT_HBC", "FEAT_HCX", "FEAT_I8MM", "FEAT_LUT", "FEAT_MTE", "FEAT_MTE2", "FEAT_NV", "FEAT_NV2", "FEAT_PAN3", "FEAT_PAuth2", "FEAT_PAuth_LR", "FEAT_RASv2", "FEAT_SCTLR2", "FEAT_SME", "FEAT_SME2", "FEAT_SME2p1", "FEAT_SME_B16B16", "FEAT_SME_F16F16", "FEAT_SME_F64F64", "FEAT_SME_F8F16", "FEAT_SME_F8F32", "FEAT_SME_I16I64", "FEAT_SME_LUTv2", "FEAT_SPECRES2", "FEAT_SSBS", "FEAT_SSBS2", "FEAT_SVE_B16B16", "FEAT_WFxT", "FEAT_XS", "v8Ap6", "v8Ap7"];

/// Grouped by encoding mask, each group sorted by value. `chips` bit `n` is
/// set when the form is absent on chip `n` (apple-m1, apple-m2, apple-m3, apple-m4, apple-m5, apple-m6). `requires` is met when
/// the PE presents every feature of one of its terms.
/// (requires, strict) of the forms whose words need more for some values of
/// an encoding field than `requires`, which takes the field's condition as
/// met: a PE that meets `requires` must meet `strict`, or the table would
/// admit words that need a withheld feature.
pub(super) static FIELD_CONDITIONED: &[(&[u64], &[u64])] = &[
    (&[0x10000000], &[0x110000000]),
    (&[0x10000000], &[0x810000000]),
];

